                },
                "server": {
                    "type": "string",
                    "oneOf": [
                        {
                            "format": "host-name"
                        },
                        {
                            "format": "ipv4"
                        },
                        {
                            "format": "ipv6"
                        }
                    ]
                }
            },
            "required": [
                "type",
                "server",
                "remotePath"
            ],
            "additionalProperties": false
        },
        "tmpfs": {
            "properties": {
                "type": {
