            "$ref": "#/definitions/nfs"
        },
        "tmpfs": {
            "$ref": "#/definitions/tmpfs"
        }
    },
    "required": [
        "diskDevice",
        "diskUUID",
        "nfs",
        "tmpfs"
    ]
}

{
    "definitions": {
        "typedterminal": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "primitive",
                        "valuespace",
                        "propertyref",
                        "keyword"
                    ]
                },
                "name": {
                    "type": "string"
                },
                "optional": {
                    "type": "boolean"
                },
                "range": {
                    "type": "array",
