                        "type": "string"
                    }
                }
            },
            "additionalProperties": false,
            "required": [
                "type",
                "name"
            ]
        },
        "stringterminal": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^string$"
                },
                "content": {
                    "type": "string"
                }
            },
            "additionalProperties": false,
            "required": [
                "type",
                "content"
            ]
        },
        "oneOf": {
            "type": "object",
            "properties": {
                "oneOf": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/component"
                    }
                },
                "nonempty": {
                    "type": "boolean"
                }
            },
            "additionalProperties": false,
            "required": [
                "oneOf"
            ]
        },
        "anyOf": {
            "type": "object",
            "properties": {
                "anyOf": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/component"
                    }
                },
                "nonempty": {
                    "type": "boolean"
                }
            },
            "additionalProperties": false,
            "required": [
                "anyOf"
            ]
        },
        "allOf": {
            "type": "object",
            "properties": {
                "allOf": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/component"
                    }
                },
                "nonempty": {
                    "type": "boolean"
                }
            },
            "additionalProperties": false,
            "required": [
                "allOf"
            ]
        },
        "sequence": {
            "type": "object",
