                            "$ref": "#/definitions/component"
                        }
                    ]
                },
                "minItems": {
                    "type": "number"
                },
                "maxItems": {
                    "type": "number"
                }
            },
            "additionalProperties": false,
            "required": [
                "type",
                "items"
